import React from "react";
import { useCurrentFrame, useVideoConfig } from "remotion";
import { Camera, ParallaxLayer, useCamera, type CameraKey } from "../camera/Camera";
import { Stage } from "../stage/Stage";
import { SceneLighting } from "../stage/SceneLighting";
import { PaperBackground } from "../paper/PaperBackground";
import { GoldFrame } from "../ornaments/GoldFrame";
import { Cloud, PalaceSkyline, SkyGradient, SunOnWire } from "../sets/Sky";
import { AgniKund, MandapBack, MandapFront, Platform } from "../sets/Mandap";
import { SacredFire, Smoke } from "../fx/Fire";
import { Character } from "../characters/Character";
import { people, wardrobe } from "../characters/cast";
import { Flower, GarlandSwag, Leaf, Petal } from "../props/Florals";
import { Diya } from "../props/Ganesh";
import { palette } from "../theme/palette";
import { EventTitle } from "../kit/EventTitle";
import { Sway } from "../kit/Idle";
import { FallingPetals } from "../kit/Particles";
import { EASE, mix, prog } from "../kit/motion";
import type { SceneProps } from "./types";
import { bi, whenBi } from "../data/i18n";

const SVG: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute", inset: 0, overflow: "visible" }}>
    {children}
  </svg>
);

// Couple placement: feet on the platform at y≈1444, either side of the fire.
const FEET = 1444;
const FIG = 560;
const TOP = FEET - FIG * 0.956;
const R_CENTER = 356;
const N_CENTER = 726;

/** Character-local (400×1000 viewBox, person scale about the feet) → scene coordinates. */
const toScene = (center: number, scale: number, lx: number, ly: number): [number, number] => {
  const x = 200 + (lx - 200) * scale;
  const y = 956 + (ly - 956) * scale;
  return [center - FIG * 0.2 + x * (FIG / 1000), TOP + y * (FIG / 1000)];
};
// The gathbandhan ties the end of Rishabh's stole to Nandita's dupatta.
const [GX0, GY0] = toScene(R_CENTER, people.rishabh.scale, 252, 486);
const [GX1, GY1] = toScene(N_CENTER, people.nandita.scale, 300, 606);
const GATH = `M${GX0} ${GY0} C${GX0 + 60} ${GY0 + 190} ${GX1 - 120} ${GY1 + 110} ${GX1} ${GY1}`;

/** Static composition first; `cameraKeys` lets the same layout be previewed with a slow push. */
/**
 * Phere — the emotional centre. Everything is slower here: a long dolly toward the fire,
 * the couple barely breathing, petals drifting, the title arriving late and holding.
 */
export const PhereScene: React.FC<SceneProps & { cameraKeys?: CameraKey[] }> = ({ inv, dur, cameraKeys }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const t = frame / fps;
  const cam = useCamera(
    cameraKeys ?? [
      { frame: 0, scale: 1, y: -20 },
      { frame: dur, scale: 1.075, y: 36, ease: EASE.cine },
    ],
  );
  const reach = prog(frame, 40, 110, EASE.inOut);
  const phere = inv.events.weddingDay.items.find((i) => i.id === "phere");

  return (
    <Stage>
      <Camera state={cam}>
        {/* BACKGROUND — golden-hour sky, sun on its wire, clouds */}
        <ParallaxLayer depth={0.15} blurStrength={0}>
          <SVG>
            <SkyGradient id="phere-sky" top="#F3D6A0" mid="#EDB47A" bottom="#E3976A" />
            <Cloud x={70} y={250} w={260} fill="#F7E2BC" line={palette.goldLight} />
            <Cloud x={720} y={640} w={220} fill="#F4D3A6" />
            <Cloud x={-40} y={560} w={200} fill="#F2CFA0" />
          </SVG>
          <PaperBackground stock="cream" seed="phere-sky" fibres={30} textureOnly />
        </ParallaxLayer>
        <ParallaxLayer depth={0.2} blurStrength={0}>
          <SVG>
            <SunOnWire t={0.742 + prog(frame, 0, dur, EASE.cine) * 0.016} />
          </SVG>
        </ParallaxLayer>

        {/* DECORATION — distant palace */}
        <ParallaxLayer depth={0.35} blurStrength={3}>
          <SVG>
            <PalaceSkyline fill="#E7BE92" y={1010} accent="#F3D5AE" />
            <PalaceSkyline fill="#D9A274" y={1140} />
          </SVG>
        </ParallaxLayer>

        {/* MIDGROUND — back pillars */}
        <ParallaxLayer depth={0.75} blurStrength={2}>
          <SVG>
            <MandapBack />
          </SVG>
        </ParallaxLayer>

        {/* STAGE — platform, fire, couple, mandap front */}
        <ParallaxLayer depth={1}>
          <SVG>
            <Platform />
            <Smoke x={540} y={1250} t={t} height={440} />
          </SVG>
          <div style={{ position: "absolute", left: R_CENTER - FIG * 0.2, top: TOP }}>
            <Sway amp={0.35} period={170}>
              <Character
                person={people.rishabh}
                outfit={wardrobe.rishabh.wedding}
                height={FIG}
                pose={{ rShoulder: mix(-10, -17, reach), rElbow: mix(-30, -44, reach), headTilt: mix(0, 3, reach) }}
              />
            </Sway>
          </div>
          <div style={{ position: "absolute", left: N_CENTER - FIG * 0.2, top: TOP }}>
            <Sway amp={0.35} period={190} phase={1.4}>
              <Character
                person={people.nandita}
                outfit={wardrobe.nandita.wedding}
                height={FIG}
                pose={{ lShoulder: mix(12, 17, reach), lElbow: mix(-32, -46, reach), headTilt: mix(0, -3, reach) }}
              />
            </Sway>
          </div>
          <SVG>
            {/* gathbandhan — the tied sash between them, passing behind the fire */}
            <path d={GATH} fill="none" stroke={palette.maroon} strokeWidth={9} strokeLinecap="round" />
            <path d={GATH} fill="none" stroke={palette.goldLight} strokeWidth={2} strokeDasharray="10 8" />
            <AgniKund />
            <SacredFire x={540} y={1352} t={t} scale={0.95} />
            {[250, 830].map((x, i) => (
              <g key={x} transform={`translate(${x - 30} 1394)`}>
                <Diya size={60} flicker={t * 3 + i} />
              </g>
            ))}
            {[140, 330, 460, 620, 760, 940].map((x, i) => (
              <Petal key={x} x={x} y={1452 + (i % 2) * 8} rot={i * 47} s={1.1} color={i % 2 ? palette.rose : palette.marigold} />
            ))}
          </SVG>
          <SVG>
            <MandapFront />
          </SVG>
        </ParallaxLayer>

        {/* slow petals drifting through the stage */}
        <ParallaxLayer depth={1.15} blurStrength={2}>
          <FallingPetals count={18} seed="phere" speed={0.55} start={20} colors={[palette.rose, palette.marigold, palette.roseLight]} />
        </ParallaxLayer>

        {/* FOREGROUND — out-of-focus garlands framing the top, petals at the bottom */}
        <ParallaxLayer depth={1.45} blurStrength={9}>
          <SVG>
            <GarlandSwag from={[-40, 120]} to={[360, 60]} sag={70} r={20} seed="fg1" tones={["orange", "yellow", "orange", "rose"]} />
            <GarlandSwag from={[760, 40]} to={[1120, 150]} sag={60} r={20} seed="fg2" tones={["yellow", "orange", "orange"]} />
            <Leaf x={40} y={1860} rot={-30} s={3} />
            <Flower x={70} y={1870} r={40} tone="orange" />
            <Flower x={150} y={1900} r={30} tone="yellow" />
            <Flower x={1030} y={1880} r={44} tone="rose" />
            <Leaf x={960} y={1890} rot={200} s={3} color={palette.greenDeep} />
          </SVG>
        </ParallaxLayer>
      </Camera>

      {/* LIGHT — golden hour key from upper right, fire glow, gentle vignette */}
      <SceneLighting
        warmth={0.45}
        keyX={72}
        keyY={20}
        spots={[
          { x: 50, y: 68, r: 38, color: "#FFB45A", intensity: 0.28 },
          { x: 73, y: 23, r: 30, color: "#FFE3A6", intensity: 0.2 },
        ]}
        vignette={0.42}
      />

      {/* TEXT — arrives late and holds, set on the courtyard floor */}
      <EventTitle
        start={70}
        top={1616}
        kicker="The Sacred Vows"
        title={phere?.title ?? "Phere"}
        titleSize={100}
        lines={[whenBi(inv.events.weddingDay.date, phere?.time), bi(inv.events.weddingDay.venue)]}
      />

      <GoldFrame />
    </Stage>
  );
};
